// client-ordering · кейсы co-13, co-14, co-15 (.qa/tests/client-ordering/) — היסטוריית הזמנות של הלקוח
// Изоляция чужих заказов — в tests/auth-security/customer-isolation.spec.ts.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.describe('client-ordering — היסטוריית הזמנות', () => {
  test.describe('buyer с заказами', () => {
    test.use({ storageState: path.resolve(__dirname, '../../../auth/buyer.json') });

    test('רשימת ההזמנות עם תאריך, פריטים, סכום וסטטוס; פירוט מלא; לשוניות #6a38cf5c @prod-safe', async ({ page }) => {
      await page.goto('/shop/orders');
      await expect(page.getByRole('heading', { level: 1, name: 'ההזמנות שלי' })).toBeVisible();
      const tabs = page.getByRole('tablist', { name: 'סינון הזמנות' });
      await expect(tabs.getByRole('tab', { name: 'הכל' })).toHaveAttribute('aria-selected', 'true');
      await expect(tabs.getByRole('tab', { name: 'פתוחות' })).toBeVisible();
      await expect(tabs.getByRole('tab', { name: 'הושלמו' })).toBeVisible();

      const rows = page.getByRole('link', { name: /^הזמנה #\d+/ });
      await expect(rows.first()).toBeVisible();
      const first = rows.first();
      await expect(first).toContainText(/\d{1,2} ב\S+ \d{4}/); // дата
      await expect(first).toContainText(/\d+ פריטים/);
      await expect(first).toContainText('₪');
      const name = (await first.innerText()).match(/#\d+/)![0];

      await first.click();
      await expect(page).toHaveURL(/\/shop\/order\/[0-9a-f-]{36}/);
      await expect(page.getByRole('heading', { level: 1, name: `הזמנה ${name}` })).toBeVisible();
      await expect(page.getByText('סה״כ', { exact: true })).toBeVisible();
      await expect(page.getByRole('heading', { name: 'פריטים' })).toBeVisible();
      await expect(page.getByText(/^\d+(\.\d+)? × ₪[\d,.]+$/).first()).toBeVisible(); // qty × מחיר פר-לקוח

      await page.getByRole('button', { name: 'חזרה להזמנות' }).click();
      await expect(page).toHaveURL(/\/shop\/orders/);
      await tabs.getByRole('tab', { name: 'הושלמו' }).click();
      await expect(tabs.getByRole('tab', { name: 'הושלמו' })).toHaveAttribute('aria-selected', 'true');
      const done = await rows.count();
      if (done === 0) await expect(page.getByText('אין הזמנות בקטגוריה הזו')).toBeVisible();
      await tabs.getByRole('tab', { name: 'פתוחות' }).click();
      await expect(tabs.getByRole('tab', { name: 'פתוחות' })).toHaveAttribute('aria-selected', 'true');
    });

    test('טלפון: כל לשונית ≥ 44×44, בלי גלילה אופקית ב-320–390, נגיעה מחליפה לשונית #203f0163 @mobile @prod-safe', async ({ page }) => {
      await page.goto('/shop/orders');
      await expect(page.getByRole('heading', { level: 1, name: 'ההזמנות שלי' })).toBeVisible({ timeout: 20_000 });
      const tabs = page.getByRole('tablist', { name: 'סינון הזמנות' });
      const names = ['הכל', 'פתוחות', 'הושלמו'];
      const vh = page.viewportSize()!.height;
      for (const width of [320, 360, 375, 390]) {
        await page.setViewportSize({ width, height: vh });
        for (const n of names) {
          const box = (await tabs.getByRole('tab', { name: n }).boundingBox())!;
          expect(box.width, `«${n}» ширина при ${width}px`).toBeGreaterThanOrEqual(44);
          expect(box.height, `«${n}» высота при ${width}px`).toBeGreaterThanOrEqual(44);
        }
        const [sw, cw] = await page.evaluate(() => [document.documentElement.scrollWidth, document.documentElement.clientWidth]);
        expect(sw, `горизонтальная прокрутка при ${width}px`).toBeLessThanOrEqual(cw);
      }
      // переключение касанием (проекты iphone/android — hasTouch)
      for (const n of ['פתוחות', 'הושלמו', 'הכל']) {
        await tabs.getByRole('tab', { name: n }).tap();
        await expect(tabs.getByRole('tab', { name: n })).toHaveAttribute('aria-selected', 'true');
      }
    });
  });

  test('לקוח חדש ללא הזמנות — מצב ריק עם קישור לקטלוג #6a38cf5c @prod-safe', async () => {
    test.skip(true, 'нужен аккаунт buyer2 (новый לקוח עסקי без заказов)');
  });
});
